      "title": "11/24~25) 1시간 40만) 20세 이상 ~ 남성) 푸드 크리에이터 온라인 화상 인터뷰",
      "source": "naver_cafe",
      "source_url": "https://m.cafe.naver.com/togetheralba/130966",
      "target_age": "",
      "target_gender": "",
      "target_condition": "이 탐나고 먹고 싶어지게 만드는 전달력을 가진 인물",
      "date": "대일 온라인 화상인터뷰 : 11월 24일(화) ~25일 (수) 중 하루 60분간 인터뷰 /시간은 확정시 안내드립니다",
      "time": "",
